import pytest
from semverrange import satisfies


class TestVersionParsing:
    """Test version format validation and parsing."""

    def test_basic_version(self):
        assert satisfies("1.2.3", "1.2.3")

    def test_version_with_leading_v(self):
        assert satisfies("v1.2.3", "v1.2.3")
        assert satisfies("v1.2.3", "1.2.3")
        assert satisfies("1.2.3", "v1.2.3")

    def test_version_with_whitespace(self):
        assert satisfies(" 1.2.3 ", "1.2.3")
        assert satisfies("1.2.3", " 1.2.3 ")

    def test_version_with_prerelease(self):
        assert satisfies("1.2.3-alpha", "1.2.3-alpha")
        assert satisfies("1.2.3-alpha.1", "1.2.3-alpha.1")
        assert satisfies("1.2.3-0", "1.2.3-0")
        assert satisfies("1.2.3-x.7.z.92", "1.2.3-x.7.z.92")

    def test_version_with_build_metadata(self):
        assert satisfies("1.2.3+build", "1.2.3+other")
        assert satisfies("1.2.3-alpha+build", "1.2.3-alpha")

    def test_invalid_version_missing_parts(self):
        with pytest.raises(ValueError):
            satisfies("1.2", "*")

    def test_invalid_version_leading_zeros(self):
        with pytest.raises(ValueError):
            satisfies("01.2.3", "*")
        with pytest.raises(ValueError):
            satisfies("1.02.3", "*")
        with pytest.raises(ValueError):
            satisfies("1.2.03", "*")

    def test_invalid_version_prerelease_leading_zero(self):
        with pytest.raises(ValueError):
            satisfies("1.2.3-01", "*")
        with pytest.raises(ValueError):
            satisfies("1.2.3-alpha.01", "*")

    def test_invalid_version_missing_prerelease(self):
        with pytest.raises(ValueError):
            satisfies("1.2.3-", "*")

    def test_invalid_version_too_many_parts(self):
        with pytest.raises(ValueError):
            satisfies("1.2.3.4", "*")

    def test_invalid_version_non_numeric_major(self):
        with pytest.raises(ValueError):
            satisfies("a.b.c", "*")


class TestVersionComparison:
    """Test version ordering according to SemVer 2.0.0."""

    def test_major_comparison(self):
        assert satisfies("2.0.0", ">1.0.0")
        assert not satisfies("1.0.0", ">2.0.0")

    def test_minor_comparison(self):
        assert satisfies("1.2.0", ">1.1.0")
        assert not satisfies("1.1.0", ">1.2.0")

    def test_patch_comparison(self):
        assert satisfies("1.1.2", ">1.1.1")
        assert not satisfies("1.1.1", ">1.1.2")

    def test_prerelease_less_than_release(self):
        assert satisfies("1.0.0-alpha", "<1.0.0")
        assert not satisfies("1.0.0", "<1.0.0")

    def test_prerelease_numeric_vs_alphanumeric(self):
        # Numeric identifiers are always lower than non-numeric
        assert satisfies("1.0.0-1", "<1.0.0-alpha")

    def test_prerelease_numeric_comparison(self):
        # Numeric identifiers compared numerically
        assert satisfies("1.0.0-2", ">1.0.0-1")
        assert satisfies("1.0.0-10", ">1.0.0-2")

    def test_prerelease_alphanumeric_comparison(self):
        # Non-numeric identifiers compared ASCII order
        assert satisfies("1.0.0-beta", ">1.0.0-alpha")

    def test_prerelease_fewer_identifiers_lower(self):
        assert satisfies("1.0.0-alpha", "<1.0.0-alpha.1")


class TestExactMatching:
    """Test exact version matching."""

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.2.3", "1.2.3", True),
            ("1.2.3", "=1.2.3", True),
            ("1.2.4", "1.2.3", False),
            ("1.2.3-alpha", "1.2.3-alpha", True),
            ("1.2.3-alpha", "1.2.3", False),
        ],
    )
    def test_exact_match(self, version, range, should_match):
        assert satisfies(version, range) == should_match


class TestComparisonOperators:
    """Test primitive comparison operators."""

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", "<2.0.0", True),
            ("2.0.0", "<2.0.0", False),
            ("1.9.9", "<2.0.0", True),
            ("1.0.0-alpha", "<1.0.0", True),
            ("1.0.0", "<1.0.0", False),
        ],
    )
    def test_less_than(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", "<=1.0.0", True),
            ("1.0.0", "<=2.0.0", True),
            ("2.0.0", "<=1.0.0", False),
            ("0.9.9", "<=1.0.0", True),
        ],
    )
    def test_less_than_or_equal(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("2.0.0", ">1.0.0", True),
            ("1.0.0", ">1.0.0", False),
            ("1.0.1", ">1.0.0", True),
            ("1.0.0", ">1.0.0-alpha", True),
        ],
    )
    def test_greater_than(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", ">=1.0.0", True),
            ("1.0.1", ">=1.0.0", True),
            ("0.9.9", ">=1.0.0", False),
            ("1.0.0-alpha", ">=1.0.0", False),
        ],
    )
    def test_greater_than_or_equal(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    def test_operator_with_whitespace(self):
        assert satisfies("2.0.0", ">= 1.0.0")
        assert satisfies("1.0.0", "<= 1.0.0")


class TestXRanges:
    """Test X-ranges with wildcards."""

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("0.0.0", "*", True),
            ("1.2.3", "*", True),
            ("99.99.99", "*", True),
            ("0.0.0", "x", True),
            ("1.2.3", "X", True),
            ("0.0.0", "", True),
        ],
    )
    def test_match_any(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", "1.x", True),
            ("1.5.7", "1.x", True),
            ("1.99.99", "1.x", True),
            ("2.0.0", "1.x", False),
            ("0.9.9", "1.x", False),
            ("1.0.0", "1", True),
            ("1.5.7", "1", True),
        ],
    )
    def test_major_x_range(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.2.0", "1.2.x", True),
            ("1.2.5", "1.2.x", True),
            ("1.2.99", "1.2.x", True),
            ("1.3.0", "1.2.x", False),
            ("1.1.9", "1.2.x", False),
            ("1.2.0", "1.2", True),
            ("1.2.5", "1.2", True),
        ],
    )
    def test_minor_x_range(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", ">1.x", False),
            ("1.5.0", ">1.x", False),
            ("2.0.0", ">1.x", True),
            ("2.5.3", ">1", True),
            ("1.9.9", ">1", False),
        ],
    )
    def test_x_range_with_comparison(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.0.0", "<1.2", False),
            ("1.1.9", "<1.2", True),
            ("1.2.0", "<1.2", False),
        ],
    )
    def test_less_than_partial_version(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.1.9", "<=1.2", True),
            ("1.2.0", "<=1.2", True),
            ("1.3.0", "<=1.2", False),
        ],
    )
    def test_less_than_or_equal_partial_version(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    @pytest.mark.parametrize(
        "version,range,should_match",
        [
            ("1.3.0", ">=1.2", True),
            ("1.2.0", ">=1.2", True),
            ("1.1.9", ">=1.2", False),
        ],
    )
    def test_greater_than_or_equal_partial_version(self, version, range, should_match):
        assert satisfies(version, range) == should_match

    def test_x_range_matches_nothing(self):
        assert not satisfies("0.0.0", ">*")
        assert not satisfies("99.99.99", ">*")
        assert not satisfies("0.0.0", "<*")
        assert not satisfies("99.99.99", "<*")


