class TestPrereleaseMatching:
    """Test special prerelease matching rules."""

    def test_prerelease_matches_prerelease_comparator_same_mnp(self):
        # Prerelease version matches if at least one comparator has prerelease with same MAJOR.MINOR.PATCH
        assert satisfies("1.2.3-alpha.7", ">1.2.3-alpha.3")

    def test_prerelease_does_not_match_different_mnp(self):
        # Prerelease version does not match comparator with different MAJOR.MINOR.PATCH
        assert not satisfies("3.4.5-alpha.9", ">1.2.3-alpha.3")

    def test_prerelease_does_not_match_wildcard(self):
        # Prerelease version does not match wildcard range without prerelease in comparator
        assert not satisfies("1.0.0-beta", "*")

    def test_prerelease_does_not_match_less_than_without_prerelease(self):
        assert not satisfies("1.0.0-beta", "<2.0.0")

    def test_prerelease_matches_less_than_with_minus_zero(self):
        # `-0` is a prerelease, so prerelease version can match it
        assert satisfies("1.0.0-beta", "<2.0.0-0")

    def test_prerelease_matches_explicit_prerelease_comparator_same_mnp(self):
        assert satisfies("1.0.0-beta", ">=1.0.0-alpha")

    def test_prerelease_x_range_expansion(self):
        # `1.x` expands to `>=1.0.0 <2.0.0-0`
        # The upper bound `<2.0.0-0` has a prerelease, so prerelease 2.0.0-x should not match
        assert not satisfies("2.0.0-alpha", "1.x")

    def test_prerelease_in_caret_range_expansion(self):
        # `^1.2.3` expands to `>=1.2.3 <2.0.0-0`
        # The upper bound has a prerelease with same MAJOR.MINOR.PATCH as 2.0.0
        assert not satisfies("2.0.0-alpha", "^1.2.3")

    def test_prerelease_in_tilde_range_expansion(self):
        # `~1.2.3` expands to `>=1.2.3 <1.3.0-0`
        assert not satisfies("1.3.0-alpha", "~1.2.3")


class TestEdgeCases:
    """Test edge cases and special scenarios."""

    def test_build_metadata_ignored_in_comparison(self):
        assert satisfies("1.2.3+build1", "1.2.3+build2")
        assert satisfies("1.2.3+build", ">=1.2.3")
        assert satisfies("1.2.4+build", ">1.2.3")

    def test_empty_range_matches_any(self):
        assert satisfies("0.0.0", "")
        assert satisfies("1.2.3", "")
        assert satisfies("99.99.99", "")

    def test_zero_versions(self):
        assert satisfies("0.0.0", "0.0.0")
        assert satisfies("0.0.1", ">0.0.0")
        assert satisfies("0.0.0", "<0.0.1")

    def test_large_version_numbers(self):
        assert satisfies("999.999.999", "999.999.999")
        assert satisfies("100.0.0", ">99.99.99")

    def test_complex_prerelease_identifiers(self):
        assert satisfies("1.0.0-x.7.z.92", "1.0.0-x.7.z.92")
        assert satisfies("1.0.0-x.7.z.93", ">1.0.0-x.7.z.92")

    def test_multiple_prerelease_dots(self):
        assert satisfies("1.0.0-alpha.beta.gamma", ">=1.0.0-alpha.beta.gamma")

    def test_whitespace_in_range(self):
        assert satisfies("1.5.0", "  >=1.0.0  <2.0.0  ")
