class TestRealWorldScenarios:
    """Test realistic version range scenarios."""

    def test_common_semver_range_caret(self):
        # ^1.2.3 is a common range meaning compatible with 1.2.3
        assert satisfies("1.2.3", "^1.2.3")
        assert satisfies("1.5.0", "^1.2.3")
        assert satisfies("1.9.9", "^1.2.3")
        assert not satisfies("2.0.0", "^1.2.3")

    def test_common_semver_range_tilde(self):
        # ~1.2.3 means patch-level changes
        assert satisfies("1.2.3", "~1.2.3")
        assert satisfies("1.2.5", "~1.2.3")
        assert not satisfies("1.3.0", "~1.2.3")

    def test_common_range_exact_or_later(self):
        assert satisfies("1.0.0", ">=1.0.0")
        assert satisfies("1.5.0", ">=1.0.0")
        assert not satisfies("0.9.9", ">=1.0.0")

    def test_common_range_major_version(self):
        # Allow major version
        assert satisfies("2.0.0", "2.x")
        assert satisfies("2.5.3", "2.x")
        assert not satisfies("3.0.0", "2.x")

