        assert satisfies("2.3.1", "1.x || 2.x")
        assert not satisfies("3.0.0", "1.x || 2.x")

    def test_prerelease_in_development(self):
        # Development versions with prerelease
        assert satisfies("1.0.0-alpha", ">=1.0.0-alpha")
        assert satisfies("1.0.0-alpha.1", ">1.0.0-alpha")
        assert not satisfies("1.0.0-alpha", "1.0.0")
